class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, qty=1):
        self.items.append((name, price, qty))

    def total(self):
        # BUG: 数量没乘进去
        return sum(price for _, price, _ in self.items)

    def discount_total(self, rate):
        return self.total() * (1 - rate)

