class Request:
    def __init__(self, path):
        self.path = path

class Response:
    def __init__(self, body=''):
        self.body = body

class App:
    def __init__(self):
        self.routes = {}

    def route(self, path):
        def deco(fn):
            self.routes[path] = fn
            return fn
        return deco

    def handle(self, request):
        handler = self.routes.get(request.path)
        if handler is None:
            return Response('404')
        return handler(request)

